import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { DriverRegistry } from "../src/dispatch/drivers.ts";
import { Dispatcher, type EtaService } from "../src/dispatch/dispatcher.ts";
import { RideService } from "../src/dispatch/rides.ts";
import { distanceKm, type LatLng } from "../src/dispatch/geo.ts";

const at = (lat: number, lng: number): LatLng => ({ lat, lng });
const downtown = at(40.0, -75.0);

// Routing service fake: answers after a round trip, about 3 minutes per km unless overridden.
function routing(override: (from: LatLng) => number | undefined = () => undefined): EtaService & { calls: number } {
    const svc = {
        calls: 0,
        async minutes(from: LatLng, to: LatLng) {
            svc.calls++;
            await tick();
            await tick();
            return override(from) ?? Math.round(distanceKm(from, to) * 3);
        },
    };
    return svc;
}

function city(eta = routing()) {
    const drivers = new DriverRegistry();
    const dispatcher = new Dispatcher(drivers, eta);
    return { drivers, dispatcher, rides: new RideService(dispatcher, drivers) };
}

test("the closest available driver is assigned", async () => {
    const { drivers, rides } = city();
    drivers.goOnline("far", "standard", at(40.02, -75.0));
    drivers.goOnline("near", "standard", at(40.005, -75.0));
    drivers.goOnline("xl-near", "xl", at(40.001, -75.0));
    const ride = await rides.request("r1", downtown);
    assert.equal(ride.status, "assigned");
    assert.equal(ride.driverId, "near");
    assert.equal(drivers.get("near")?.rideId, ride.id);
});

test("a driver with a long road ETA is skipped for the next closest", async () => {
    const acrossRiver = at(40.004, -75.0);
    const { drivers, rides } = city(routing((from) => (from.lat === acrossRiver.lat ? 25 : undefined)));
    drivers.goOnline("bridge", "standard", acrossRiver);
    drivers.goOnline("same-side", "standard", at(40.01, -75.0));
    const ride = await rides.request("r1", downtown);
    assert.equal(ride.driverId, "same-side");
    assert.equal(drivers.isAvailable("bridge"), true);
});

test("two riders requesting at the same moment get different drivers", async () => {
    const { drivers, rides } = city();
    drivers.goOnline("d1", "standard", at(40.002, -75.0));
    drivers.goOnline("d2", "standard", at(40.008, -75.0));
    const [a, b] = await Promise.all([rides.request("alice", downtown), rides.request("bob", at(40.001, -75.0))]);
    console.log("assignments:", { alice: a.driverId, bob: b.driverId });
    assert.equal(a.status, "assigned");
    assert.equal(b.status, "assigned");
    assert.notEqual(a.driverId, b.driverId);
});

test("with one driver left, the second simultaneous request gets no_driver", async () => {
    const { drivers, rides } = city();
    drivers.goOnline("solo", "standard", at(40.003, -75.0));
    const results = await Promise.all([rides.request("alice", downtown), rides.request("bob", downtown)]);
    assert.deepEqual(results.map((r) => r.status).sort(), ["assigned", "no_driver"]);
    const winner = results.find((r) => r.status === "assigned");
    assert.equal(drivers.get("solo")?.rideId, winner?.id);
});

test("completing a ride frees the driver at the drop-off point", async () => {
    const { drivers, rides } = city();
    drivers.goOnline("d1", "standard", at(40.002, -75.0));
    const first = await rides.request("alice", downtown);
    assert.equal((await rides.request("bob", downtown)).status, "no_driver");
    rides.complete(first.id, at(40.03, -75.0));
    assert.deepEqual(drivers.get("d1")?.location, at(40.03, -75.0));
    const next = await rides.request("carol", at(40.031, -75.0));
    assert.equal(next.driverId, "d1");
    assert.throws(() => rides.complete(first.id, downtown), /not in progress/);
});

test("in a rush of requests no driver is booked on two rides", async () => {
    const { drivers, rides } = city();
    for (let i = 1; i <= 5; i++) drivers.goOnline(`d${i}`, "standard", at(40 + i * 0.002, -75.0));
    const all = await Promise.all(Array.from({ length: 7 }, (_, i) => rides.request(`rider${i}`, at(40 + i * 0.001, -75.0))));
    const assigned = all.filter((r) => r.status === "assigned").map((r) => r.driverId);
    assert.ok(assigned.length >= 3);
    assert.equal(new Set(assigned).size, assigned.length);
    for (const r of all.filter((r) => r.status === "assigned")) assert.equal(drivers.get(r.driverId!)?.rideId, r.id);
});

test("drivers out of range or on a ride are never asked for an ETA", async () => {
    const eta = routing();
    const { drivers, rides } = city(eta);
    drivers.goOnline("busy", "standard", at(40.001, -75.0));
    drivers.markBusy("busy", "ride-0");
    drivers.goOnline("suburbs", "standard", at(40.2, -75.0));
    const ride = await rides.request("alice", downtown);
    assert.equal(ride.status, "no_driver");
    assert.equal(eta.calls, 0);
});
